/* TQPNet extends the approved collection with the exact exported SVG keyframes. */
(() => {
  'use strict';
  const base = window.SolarisAbstracts;
  if (!base) return;
  const key = 'tqpnet-2610-38079';
  let source, figure, tracks, loadError;
  const extraReady = (async () => {
    const packed = Uint8Array.from(atob(''), c => c.charCodeAt(0));
    source = await new Response(new Blob([packed]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
  })().catch(error => { loadError = error; });
  function create(scene) {
    if (scene !== key) return base.create(scene);
    if (loadError) throw loadError;
    if (!source) throw new Error('Await SolarisAbstracts.ready before creating TQPNet.');
    if (!figure) {
      const parsed = new DOMParser().parseFromString(source, 'image/svg+xml');
      if (parsed.querySelector('parsererror')) throw new Error('Invalid TQPNet SVG');
      figure = document.importNode(parsed.documentElement, true);
      tracks = [...figure.querySelectorAll('animate')].map(animation => {
        const values = animation.getAttribute('values').split(';');
        const discrete = animation.getAttribute('calcMode') === 'discrete';
        const duration = Number.parseFloat(animation.getAttribute('dur'));
        if (!discrete && values.some(value => !Number.isFinite(Number(value)))) throw new Error('Unsupported TQPNet interpolation');
        const track = {element: animation.parentElement, attribute: animation.getAttribute('attributeName'), values,
          times: animation.getAttribute('keyTimes').split(';').map(value => Number(value) * duration), duration, discrete};
        animation.remove();
        return track;
      });
    }
    // One SVG is moved between its card and enlarged view, matching the collection.
    return figure;
  }
  function render(svg, scene, seconds) {
    if (scene !== key) return base.render(svg, scene, seconds);
    if (!Number.isFinite(seconds) || seconds < 0) throw new Error('Animation time must be finite seconds.');
    for (const track of tracks) {
      const time = seconds % track.duration;
      let index = 0;
      while (index + 1 < track.times.length && track.times[index + 1] <= time) index++;
      let value = track.values[index];
      if (!track.discrete && index + 1 < track.times.length) {
        const ratio = (time - track.times[index]) / (track.times[index + 1] - track.times[index]);
        value = Number(value) + ratio * (Number(track.values[index + 1]) - Number(value));
      }
      track.element.setAttribute(track.attribute, String(value));
    }
  }
  window.SolarisAbstracts = Object.freeze({version: base.version, ready: Promise.all([base.ready, extraReady]),
    keys: Object.freeze([...base.keys, key]), create, render, initialTime: base.initialTime});
})();
